package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.List;

import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.impl.MapBindingSet;
import org.junit.jupiter.api.Test;

class BlankNodeResultBagTest {
	@Test
	void oneCorrespondenceSpansDuplicatesNestedTermsAndInputIdentities() {
		var vf = SimpleValueFactory.getInstance();
		var input = vf.createBNode("known");
		var first = vf.createBNode("first");
		var second = vf.createBNode("second");
		var alias = vf.createBNode("alias");
		var other = vf.createBNode("other");
		var predicate = vf.createIRI("urn:test:p");
		BindingSet anchors = row("input", input);
		var term = row("term", vf.createTripleTerm(first, predicate, vf.createTripleTerm(input, predicate, second)));
		var copy = row("term", vf.createTripleTerm(alias, predicate, vf.createTripleTerm(input, predicate, other)));
		var a = row("node", first);
		var b = row("node", alias);
		List<BindingSet> expected = List.of(a, term, a);
		assertThat(BlankNodeExecutionBenchmark.sameBag(expected, List.of(copy, b, b), anchors)).isTrue();
		assertThat(BlankNodeExecutionBenchmark.sameBag(expected, List.of(copy, b), anchors)).isFalse();
		assertThat(BlankNodeExecutionBenchmark.sameBag(expected, List.of(copy, b, row("node", other)), anchors))
				.isFalse();
		var collapsed = row("term",
				vf.createTripleTerm(alias, predicate, vf.createTripleTerm(input, predicate, alias)));
		assertThat(BlankNodeExecutionBenchmark.sameBag(expected, List.of(collapsed, b, b), anchors)).isFalse();
		var moved = row("term", vf.createTripleTerm(alias, predicate, vf.createTripleTerm(second, predicate, other)));
		assertThat(BlankNodeExecutionBenchmark.sameBag(expected, List.of(moved, b, b), anchors)).isFalse();
	}

	private static BindingSet row(String name, Value value) {
		var row = new MapBindingSet();
		row.addBinding(name, value);
		return row;
	}
}
